DROP TABLE IF EXISTS `psychologist_community_memberships`;
CREATE TABLE `psychologist_community_memberships` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `community_id` bigint unsigned NOT NULL,
  `psiholog_id` bigint unsigned NOT NULL,
  `initiated_by` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requested_by_user_id` bigint unsigned DEFAULT NULL,
  `reviewed_by_user_id` bigint unsigned DEFAULT NULL,
  `responded_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `psych_community_member_unique` (`community_id`,`psiholog_id`),
  KEY `psychologist_community_memberships_psiholog_id_foreign` (`psiholog_id`),
  KEY `psychologist_community_memberships_requested_by_user_id_foreign` (`requested_by_user_id`),
  KEY `psychologist_community_memberships_reviewed_by_user_id_foreign` (`reviewed_by_user_id`),
  KEY `psychologist_community_memberships_status_community_id_index` (`status`,`community_id`),
  CONSTRAINT `psychologist_community_memberships_community_id_foreign` FOREIGN KEY (`community_id`) REFERENCES `psychologist_communities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `psychologist_community_memberships_psiholog_id_foreign` FOREIGN KEY (`psiholog_id`) REFERENCES `psihologi` (`id`) ON DELETE CASCADE,
  CONSTRAINT `psychologist_community_memberships_requested_by_user_id_foreign` FOREIGN KEY (`requested_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `psychologist_community_memberships_reviewed_by_user_id_foreign` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


--
-- Table: romania_counties
--
DROP TABLE IF EXISTS `romania_counties`;
CREATE TABLE `romania_counties` (
  `code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `map_x` decimal(5,2) NOT NULL,
  `map_y` decimal(5,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


--
-- Table: romania_localities
--
DROP TABLE IF EXISTS `romania_localities`;
CREATE TABLE `romania_localities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `county_code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `siruta` int unsigned DEFAULT NULL,
  `latitude` decimal(9,6) DEFAULT NULL,
  `longitude` decimal(9,6) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `romania_localities_county_code_name_unique` (`county_code`,`name`),
  UNIQUE KEY `romania_localities_siruta_unique` (`siruta`),
  CONSTRAINT `romania_localities_county_code_foreign` FOREIGN KEY (`county_code`) REFERENCES `romania_counties` (`code`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=194 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


--
-- Table: romania_location_aliases
--
DROP TABLE IF EXISTS `romania_location_aliases`;
CREATE TABLE `romania_location_aliases` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `alias` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `normalized_alias` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `county_code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `locality_id` bigint unsigned DEFAULT NULL,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `romania_location_aliases_unique` (`normalized_alias`,`county_code`,`locality_id`),
  KEY `romania_location_aliases_county_code_foreign` (`county_code`),
  KEY `romania_location_aliases_locality_id_foreign` (`locality_id`),
  KEY `romania_location_aliases_normalized_alias_index` (`normalized_alias`),
  CONSTRAINT `romania_location_aliases_county_code_foreign` FOREIGN KEY (`county_code`) REFERENCES `romania_counties` (`code`) ON DELETE CASCADE,
  CONSTRAINT `romania_location_aliases_locality_id_foreign` FOREIGN KEY (`locality_id`) REFERENCES `romania_localities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


--
-- Table: sessions
--
DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `payload` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_activity` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table: settings
--
DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci,
  `data_type` enum('text','integer','float','boolean','json') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


--
-- Table: specialization_keywords
--
